class _SessionJSONEncoder(jsonlib.JSONEncoder):
    """Custom JSON encoder class for TheHive session."""

    def default(self, o: Any):
        if isinstance(o, UserDict):
            return o.data
        return super().default(o)


class TheHiveSession:
    def __init__(
        self,
        url: str,
        apikey: Optional[str] = None,
        username: Optional[str] = None,
        password: Optional[str] = None,
        verify: VerifyValue = True,
        max_retries: RetryValue = DEFAULT_RETRY,
    ):
        self.hive_url = self._sanitize_hive_url(url)
        self.verify = verify
        self.headers = {"User-Agent": f"thehive4py/{__version__}"}
        self.max_retries = max_retries

        if username and password:
            import base64
            credentials = f"{username}:{password}"
            encoded_credentials = base64.b64encode(credentials.encode()).decode()
            self.headers["Authorization"] = f"Basic {encoded_credentials}"
        elif apikey:
            self.headers["Authorization"] = f"Bearer {apikey}"
        else:
            raise TheHiveError(
                "Either apikey or the username/password combination must be provided!"
            )

    def _sanitize_hive_url(self, hive_url: str) -> str:
        """Sanitize the base url for the client."""
        if hive_url.endswith("/"):
            return hive_url[:-1]
        return hive_url

    def _create_request(self, method: str, url: str, data=None, headers=None):
        """Create a urllib request object."""
        if headers is None:
            headers = {}

        # Merge with session headers
        req_headers = {**self.headers, **headers}

        # Create request
        req = urllib.request.Request(url, data=data, headers=req_headers, method=method)
        return req

    def _make_request_with_retry(self, req):
        """Make request with retry logic."""
        last_exception = None

        for attempt in range(self.max_retries + 1):
            try:
                # Configure SSL context if needed
                if not self.verify:
                    context = ssl.create_default_context()
                    context.check_hostname = False
                    context.verify_mode = ssl.CERT_NONE
                else:
                    context = None

                response = urllib.request.urlopen(req, context=context)
                return response
            except urllib.error.HTTPError as e:
                last_exception = e
                if attempt >= self.max_retries:
                    raise
                # Exponential backoff could be added here
            except urllib.error.URLError as e:
                last_exception = e
                if attempt >= self.max_retries:
                    raise
                # Exponential backoff could be added here

        raise last_exception

    def make_request(
        self,
        method: str,
        path: str,
        params=None,
        data=None,
        json=None,
        files=None,
        download_path: Union[str, PathLike, None] = None,
    ) -> Any:
