        endpoint_url = f"{self.hive_url}{path}"
        if params:
            query_string = urlencode(params)
            endpoint_url = f"{endpoint_url}?{query_string}"

        headers = {}
        request_data = None

        if json:
            request_data = jsonlib.dumps(json, cls=_SessionJSONEncoder).encode('utf-8')
            headers["Content-Type"] = "application/json"
        elif data:
