            raise NotImplementedError("File uploads not yet implemented with urllib")

        req = self._create_request(method, endpoint_url, data=request_data, headers=headers)
        response = self._make_request_with_retry(req)

        return self._process_response(response, download_path=download_path)

    def _process_response(
        self,
        response,
        download_path: Union[str, PathLike, None] = None,
    ):
        # Create a response-like object for compatibility
        class ResponseWrapper:
            def __init__(self, response):
                self.response = response
                self.status_code = response.getcode()
                self.ok = 200 <= self.status_code < 300
                self.headers = dict(response.headers)

            def json(self):
                try:
                    return jsonlib.loads(self.text)
                except jsonlib.JSONDecodeError:
                    raise ValueError("JSON decode error")

            @property
            def text(self):
                return self.response.read().decode('utf-8')

            def iter_content(self, chunk_size=4096):
                while True:
                    chunk = self.response.read(chunk_size)
                    if not chunk:
                        break
                    yield chunk

        wrapped_response = ResponseWrapper(response)

        if wrapped_response.ok:
            if download_path is None:
                return self._process_text_response(wrapped_response)
            else:
                self._process_stream_response(
                    response=wrapped_response, download_path=download_path
                )
